function rstName(k){ const r=RST_ITEMS.find(x=>x[0]===k); return r?r[1]:k }
function rstFmtD(ts){ return new Date(ts).toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'long',day:'numeric',month:'numeric',year:'numeric'})+'، '+new Date(ts).toLocaleTimeString('ar-IQ-u-nu-latn',{hour:'numeric',minute:'2-digit'}) }
function rstRender(){
  const box=document.getElementById('rstList'), log=document.getElementById('rstLog'); if(!box) return;
  box.innerHTML=RST_ITEMS.map(([k,t,sub,now])=>{ const v=now();
    return `<label class="rst-ck"><input type="checkbox" data-rst="${k}"><span><b>${esc(t)}</b><small>${k==='sales'?'من آخر تصفير: '+fmt(v.in)+' طلب · '+fmt(v.out)+' د.ع':'داخل '+fmt(Math.round(v.in*100)/100)+' · طالع '+fmt(Math.round(v.out*100)/100)}${sub?' — '+esc(sub):''}</small></span></label>` }).join('');
  const L=(settings.resets||[]).slice().reverse();
  log.innerHTML=L.length?L.map(r=>`<div class="rst-row"><div class="rst-d">${esc(rstFmtD(r.ts))}</div>${r.items.map(k=>{const b=r.before[k]||{};return `<div class="rst-i">${esc(rstName(k))}: ${k==='sales'?fmt(b.in)+' طلب بمبلغ '+fmt(b.out)+' د.ع':'داخل '+fmt(Math.round((b.in||0)*100)/100)+' · طالع '+fmt(Math.round((b.out||0)*100)/100)+' '+esc(b.u||'')}</div>`}).join('')}</div>`).join(''):'<p class="note">بعد ما صفرت شي.</p>';
}
function rstDo(){
  const ks=[...document.querySelectorAll('[data-rst]:checked')].map(c=>c.dataset.rst);
  if(!ks.length){ toast('اختار شنو تصفر'); return }
  uiYes('تصفر: '+ks.map(rstName).join('، ')+'؟ الطلبات والتقارير القديمة تبقى محفوظة.',async()=>{
    try{ await fetch(BK_URL+'?a=save&keep=1',{method:'POST',headers:{'Content-Type':'application/json','X-Safi-Key':bkKey()},body:JSON.stringify(bkData())}) }catch(_){}
    const ts=Date.now(), before={};
    RST_ITEMS.forEach(([k,,, now,reset])=>{ if(ks.includes(k)){ before[k]=now(); reset() } });
    settings.resets=(settings.resets||[]).concat([{ts,items:ks,before}]).slice(-100);
    settings.rstAt=settings.rstAt||{}; ks.forEach(k=>settings.rstAt[k]=ts);
    if(settings.low&&settings.low.ack) ks.forEach(k=>delete settings.low.ack[k]);
    saveAll(); try{ fillStore() }catch(_){} try{ boxCalc() }catch(_){} rstRender(); try{ lowCheck() }catch(_){}
    toast('انصفر، وانحفظت نسخة كاملة قبل التصفير');
  });
}
